export class BalanceModel {
    private _startBalance: number = 0;
    private _endBalance: number = 0;

    public get startBalance(): number {
        return this._startBalance;
    }

    public get endBalance(): number {
        return this._endBalance;
    }

    public setData(start: number, end: number): void {
        this._startBalance = start;
        this._endBalance = end;
    }
}